// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 blockNum, uint256 warpTime, address sender) public {
        vm.assume(sender != address(0));
        vm.assume(blockNum > 0);
        vm.assume(warpTime > 0);

        vm.roll(blockNum);
        vm.warp(warpTime);
        vm.deal(sender, 10 ether);
        vm.prank(sender);
        (bool success, ) = address(c).call{value: 10 ether}("");
        require(success, "fallback call failed");

        if (blockNum % 15 == 0) {
            assertEq(address(c).balance, 0);
        }
    }
}
